"""Cited, independently worded food context; never a guessed family-recipe origin."""
from html import escape
import re

from bs4 import BeautifulSoup

# Rules use dish names first, then facts tied to ingredients actually listed.
FACTS = [
    ("craft", r"^play dough recipe$", "", "This is a nonfood craft preparation, not a dish to eat. The source combines flour, salt, water, oil and cream of tartar, then uses gentle heat and stirring to form a moldable dough. Its optional scent does not turn it into food.", "Source: this page's original ingredient and method record", "#main-content"),
    ("root-beer", r"^root beer$", "", "Root beer's name reflects an American tradition of flavoring drinks with roots and herbs. Commercial versions became successful in the late nineteenth century; that beverage history does not identify the maker of this particular extract-based recipe.", "Britannica: Root beer", "https://www.britannica.com/topic/root-beer"),
    ("popcorn", r"\bpopcorn\b", "", "A popcorn kernel traps moisture inside a strong hull. Heating turns that moisture into steam until the hull gives way and the starchy interior expands into the familiar fluffy snack; this is a property of popping corn, not every kind of dried corn.", "Britannica: Popcorn", "https://www.britannica.com/topic/popcorn"),
    ("sushi", r"\bsushi\b", "", "Sushi is built around vinegared rice, not necessarily raw fish. Vegetables, egg and cooked seafood can all be part of sushi; a bowl keeps the rice and toppings together without needing a rolled shape.", "Britannica: Sushi", "https://www.britannica.com/topic/sushi"),
    ("shepherds-pie", r"shepherd.?s pie", "", "Shepherd's pie belongs to the British Isles tradition of meat-and-vegetable casseroles topped with mashed potatoes. The related name cottage pie appears in eighteenth-century British cookbooks; the potato topping, rather than pastry, is a defining feature of today's dish.", "Britannica: Shepherd's pie", "https://www.britannica.com/topic/shepherds-pie"),
    ("cookie", r"\bcookies?\b", "", "The word cookie comes from the Dutch koekje, meaning a little cake. Rolled, dropped and bar cookies are different ways of shaping this broad baking family, rather than names for one fixed dough.", "Britannica: Cookie", "https://www.britannica.com/topic/cookie-food"),
    ("bundt", r"\bbundt\b", "", "The familiar Bundt shape comes from a fluted ring pan trademarked by Nordic Ware in 1950. Its popularity grew after a Tunnel of Fudge cake took second place in the 1966 Pillsbury Bake-Off; that is pan history, not the origin of this particular recipe.", "Smithsonian: A Short History of Cakes", "https://www.si.edu/stories/short-history-cakes"),
    ("cake", r"\b(cake|cakes|cupcakes)\b", "", "Many modern cakes share flour, fat, sugar and eggs with other baked foods, but their proportions and mixing methods create a different result from bread or cookies. Cake history covers many styles; it does not establish who first made this family's version.", "Smithsonian: A Short History of Cakes", "https://www.si.edu/stories/short-history-cakes"),
    ("bread", r"\b(bread|rolls|pretzels|pita|bagels|focaccia|naan)\b", "", "Bread has been part of human food traditions since prehistoric times. The broad family includes both leavened and unleavened doughs, so the name alone does not mean a recipe uses yeast or needs a long rise.", "Britannica: Bread", "https://www.britannica.com/topic/bread"),
    ("pasta", r"\b(pasta|spaghetti|lasagna|lasagne|fettuccine|linguine|penne|macaroni|ravioli|tortellini)\b", "", "Italian-style pasta is commonly made with durum-wheat semolina. Pasta shapes are not just decorative: their ridges, hollows and surfaces hold sauces differently, which helps explain the many shapes used for otherwise similar ingredients.", "Britannica: Pasta", "https://www.britannica.com/topic/pasta"),
    ("soup", r"\b(soup|chowder|zuppa|stew|bisque)\b", "", "Soup is a broad food family built from ingredients cooked in liquid. Broths can begin with vegetables, meat, poultry or fish, while pureed vegetables, cream or other thickeners give some soups their body; soup need not always be served hot.", "Britannica: Soup", "https://www.britannica.com/topic/soup"),
    ("salad", r"\b(salad|coleslaw)\b", "", "Salad does not have to mean a bowl of leafy greens. The family also includes vegetables, fruit, grains, pasta and meat or seafood, and some potato salads are served warm rather than chilled.", "Britannica: Salad", "https://www.britannica.com/topic/salad"),
    ("sandwich", r"\b(sandwich|sandwiches|reuben|wraps)\b", "", "The English name sandwich was adopted in the eighteenth century in connection with John Montagu, the fourth Earl of Sandwich. That naming history is not a claim that he invented eating a filling with bread, or that a modern wrap follows his recipe.", "Britannica: Sandwich", "https://www.britannica.com/topic/sandwich"),
    ("curry", r"\bcurr(y|ies)\b", "", "The English word curry comes from the Tamil word kari, referring to sauce. Curry is not a single spice mixture: ingredients and seasoning vary by region, dish and cook, so this background should not be read as an origin story for every curry recipe.", "Britannica: Curry", "https://www.britannica.com/topic/curry"),
    ("tortilla", r"\b(tacos?|burritos?|enchiladas?|quesadillas?|crunchwrap)\b", "", "Tortillas provide the foundation for several distinct dishes. Tacos use a folded tortilla, burritos wrap a filling, and enchiladas are covered with sauce; the filling alone does not determine the name.", "Britannica: Tortilla", "https://www.britannica.com/topic/tortilla"),
    ("ice-cream", r"\bice cream\b", "", "Ice cream usually combines dairy, sugar and flavoring, while frozen custard also uses eggs. Those are related frozen-dessert traditions, not interchangeable formulas; the ingredients and method for this particular version remain the guide.", "Britannica: Ice cream", "https://www.britannica.com/topic/ice-cream"),
    ("custard", r"\b(custard|quiche|flan|creme brulee|crème brûlée)\b", "", "Custard thickens as heat causes egg proteins to set. That same principle appears in both sweet desserts and savory quiches; a custard's flavor does not have to be sweet.", "Britannica: Custard", "https://www.britannica.com/topic/custard"),
    ("gelatin", "", r"\b(gelatin|jell.?o)\b", "Gelatin's ability to form a gel comes from collagen, an animal protein. It is the setting ingredient behind many molded desserts and salads, so it is different from plant-based thickeners even when the finished dishes look similar.", "Britannica: Gelatin", "https://www.britannica.com/topic/gelatin"),
    ("leavening", "", r"\bbaking (powder|soda)\b", "Baking powder and baking soda can raise a batter by releasing carbon dioxide rather than waiting for yeast fermentation. They work differently and are not automatic one-for-one substitutes, so the leavener specified in this recipe matters.", "King Arthur Baking: Baking soda vs. baking powder", "https://www.kingarthurbaking.com/blog/2021/09/10/baking-soda-vs-baking-powder-substitutions"),
    ("yeast", "", r"\byeast\b", "During proofing, yeast fermentation releases carbon dioxide that helps dough rise. The bubbles explain why rising time is part of many bread methods, rather than merely a pause between mixing and baking.", "Britannica: Bread", "https://www.britannica.com/topic/bread"),
    ("mayonnaise", "", r"\bmayonnaise\b", "Mayonnaise is an emulsion: egg yolk helps keep oil dispersed in a thick sauce. Lemon juice or vinegar supplies acidity, and the resulting sauce can become a base for many dressings and dips.", "Britannica: Mayonnaise", "https://www.britannica.com/topic/mayonnaise"),
    ("coconut", "", r"\bcoconut\b", "Coconut milk is made from the coconut's grated flesh mixed with water; it is not the clear coconut water found inside the fruit. The same fruit also provides flesh that can be eaten fresh or dried, explaining its different forms in cooking.", "Britannica: Coconut", "https://www.britannica.com/plant/coconut"),
    ("peanut", "", r"\bpeanut", "Despite their name, peanuts are legumes rather than true botanical nuts. Their pods develop underground after flowering, which is why groundnut is another common name for the same food.", "Britannica: Peanut", "https://www.britannica.com/plant/peanut"),
    ("rice", "", r"\b(rice|arborio|basmati)\b", "Rice is the edible grain of a grass, and it is used far beyond a plain side dish. It can also be ground into flour or made into noodles and drinks, so rice-based recipes can have very different textures and roles at the table.", "Britannica: Rice", "https://www.britannica.com/plant/rice"),
    ("potato", "", r"(?<!sweet )\bpotatoes?\b", "The potato we eat is a tuber: a swollen part of an underground stem, rather than a root. The plant is native to the Andes, while the sweet potato is a different plant; these facts describe the ingredient, not the origin of this particular dish.", "Britannica: Potato", "https://www.britannica.com/plant/potato"),
    ("cheese", "", r"\b(cheese|cheddar|parmesan|mozzarella|ricotta|brie|feta|queso)\b", "Cheese starts when milk proteins form curds that separate from the liquid whey. Differences in milk, cultures, moisture and aging help produce the many textures and flavors cooks use in otherwise quite different dishes.", "Britannica: Cheese", "https://www.britannica.com/topic/cheese"),
    ("chocolate", "", r"\b(chocolate|cocoa|cacao)\b", "Chocolate comes from processed cacao beans and has a history as a drink as well as a confection. White chocolate uses cocoa butter with sugar and milk ingredients rather than the cocoa solids that give dark chocolate its color.", "Britannica: Chocolate", "https://www.britannica.com/topic/chocolate"),
    ("vanilla", "", r"\bvanilla\b", "Natural vanilla comes from the cured seed pods of a tropical climbing orchid. Curing develops the familiar aroma, so the dark, fragrant vanilla bean used in cooking is not simply a freshly picked pod.", "Britannica: Vanilla", "https://www.britannica.com/plant/vanilla"),
    ("tomato", "", r"\btomato(es)?\b", "A tomato is botanically a fruit even though cooks commonly use it as a vegetable. Its wild ancestors came from the South American Andes, and tomatoes reached Europe in the sixteenth century; that ingredient history is separate from any modern sauce recipe.", "Britannica: Tomato", "https://www.britannica.com/plant/tomato"),
    ("avocado", "", r"\bavocados?\b", "Avocados were cultivated in tropical America before the Spanish conquest. The edible flesh comes from a fruit grown on a tree, even though its creamy texture makes it especially familiar in savory dishes such as guacamole.", "Britannica: Avocado", "https://www.britannica.com/plant/avocado"),
    ("allium", "", r"\b(garlic|onions?|shallots?|chives?|leeks?|scallions?)\b", "Onions, garlic, leeks and chives belong to the same plant genus, Allium. Their related aromas explain why these plants appear so often as seasonings, despite the different shapes and textures of their bulbs and leaves.", "Britannica: Allium", "https://www.britannica.com/plant/allium-plant"),
    ("almond", "", r"\b(almonds?|marzipan)\b", "The almond used in cooking is an edible seed. Sweet almonds can be eaten or ground into meal and paste, which is why the same ingredient can appear as a crunchy topping, a flour-like mixture or a smooth filling.", "Britannica: Almond", "https://www.britannica.com/plant/almond"),
    ("honey", "", r"\bhoney\b", "Bees make honey from flower nectar and remove moisture as it ripens. Different nectar sources influence its color and flavor, so honeys can taste quite different even before they are added to a recipe.", "Britannica: Honey", "https://www.britannica.com/topic/honey"),
    ("apple", "", r"\b(apples?|apple juice|cider)\b", "Apples are one of the world's widely cultivated tree fruits, used fresh, cooked or pressed for juice and cider. Those different forms come from the same fruit family, but their moisture and texture are not interchangeable in a particular recipe.", "Britannica: Apple", "https://www.britannica.com/plant/apple-fruit-and-tree"),
    ("sweet-potato", "", r"\bsweet potatoes?\b", "Sweet potatoes belong to the morning glory family, not the same plant family as ordinary potatoes. The part eaten is an enlarged root, and its uses range from savory vegetable dishes to sweet pie fillings.", "Britannica: Sweet potato", "https://www.britannica.com/plant/sweet-potato"),
    ("butter", "", r"\bbutter\b", "Butter is made by churning cream and has long served both as a spread and a cooking fat. Sweet cream butter describes the cream used to make it; that label alone does not mean the butter is unsalted.", "Britannica: Butter", "https://www.britannica.com/topic/butter"),
    ("soy-sauce", "", r"\bsoy sauce\b", "Traditionally brewed soy sauce develops through fermentation of soybeans, often with wheat and salt. It belongs to several East and Southeast Asian cooking traditions, with distinct styles rather than one universal formula.", "Britannica: Soy sauce", "https://www.britannica.com/topic/soy-sauce"),
    ("carbonation", "", r"\bcarbonated water\b", "Carbonation means adding carbon dioxide to a drink, which gives sparkling water and soda their bubbles and tang. Here the source starts with carbonated water, so the fizz is separate from the syrup and dairy flavorings.", "Britannica: Carbonation", "https://www.britannica.com/science/carbonation"),
    ("smoke", "", r"\bliquid smoke\b", "Smoking has a long role in adding flavor to meat and fish as well as in traditional preservation. This oven recipe uses bottled smoke flavoring instead; that is not the same process, and adding the flavoring is not a food-preservation method.", "Britannica: Smoking", "https://www.britannica.com/topic/smoking-food-preservation"),
]


def dish_note(title: str, body: str) -> str:
    soup = BeautifulSoup(body, "html.parser")
    if soup.find("h2", string="Reference, not a standalone recipe"):
        return ""
    ingredients = " ".join(node.get_text(" ", strip=True)
                           for node in soup.select("li.recipe-ingredient"))
    for key, name_pattern, ingredient_pattern, text, label, url in FACTS:
        if ((name_pattern and re.search(name_pattern, title, re.I)) or
                (ingredient_pattern and re.search(ingredient_pattern, ingredients, re.I))):
            break
    else:
        raise ValueError(f"No reviewed food-context fact for recipe: {title}")
    return (
        f'<details class="dish-note" data-note-topic="{key}">'
        '<summary><h2>About this dish / Did you know?</h2></summary>'
        f'<p>{escape(text)}</p><p class="note-source">{"Craft source" if key == "craft" else "Food context"}: '
        f'<a href="{escape(url, quote=True)}">{escape(label)}</a>. '
        + ('' if key == "craft" else
           'This is background about the dish family or a listed ingredient, not a verified '
           'origin story for this individual recipe.') + '</p></details>'
    )
